#ifndef BWTL_REUSE_PROMPT_H
#define BWTL_REUSE_PROMPT_H
static const wchar_t reuse_prompt[]=L"\n第101—110项：特征复用与参数化。每次一条原生协议，等待实际回执后继续；默认不保存。先 CREO_OP REUSE_INFO 模型 读取真实尺寸符号与参照。几何复用用于独立普通单实体零件，不能操作装配内组件。\n"
L"101：CREO_OP REUSE_MIRROR 模型 新特征名 PLANE:镜像面或SURFACE:平面 特征名1 特征名2 [更多特征]。2至8个孔、拉伸加减料、圆角、倒角最终面作为整体作关联几何镜像；需包含完整相关面，不把几何镜像说成复制可独立编辑的全部源特征树。\n"
L"102：CREO_OP REUSE_GRID 模型 新阵列名 种子特征 PLANE:方向1 行数 行距 POS|NEG PLANE:方向2 列数 列距 POS|NEG。两方向平面法向必须正交；每向2至20个、合计不超过64。种子是未编组、未阵列的孔或拉伸特征。方向参照必须先于种子存在。\n"
L"103：CREO_OP REUSE_CURVE 模型 新阵列名 种子特征 CURVE:实际单曲线 COUNT 数量 POS|NEG；或 SPACING 间距 POS|NEG。沿原生曲线路径排列，不用直线阵列冒充曲线阵列。路径应先于种子存在，不能引用后建的路径。\n"
L"104：先 CREO_OP REUSE_POINT_SKETCH 模型 新点草绘 PLANE:草绘面 PLANE:定向基准 x1 y1 x2 y2 [更多点] 创建2至12个草绘点，坐标按该草绘局部坐标毫米；再 CREO_OP REUSE_POINTS 模型 新阵列名 种子特征 SKETCH:点草绘。点草绘须在种子特征之前创建，也可为已有外部草绘，不能以任意轮廓当点集。\n"
L"105：CREO_OP REUSE_SKIP 模型 阵列名 实例序号 SKIP|RESTORE。序号从1开始，1是种子不能跳过；先读取真实实例顺序，禁止猜行列映射。本版通过独立原生移除曲面特征可逆排除实例几何，保留原阵列和实例ID，不等同于阵列编辑器点选排除。仅支持可完整移除补面的成员；恢复仅删除本工具的无后续子特征排除特征。必须按实际回执解释，不能称成员已原生抑制。\n"
L"106：CREO_OP REUSE_GROUP 模型 新组名 特征名1 特征名2 [更多]。2至8个特征必须按当前重生成次序连续，未编组也未阵列；不能自动把夹在中间但用户未选的特征纳入组。\n"
L"107：CREO_OP REUSE_UDF_SAVE 模型 库名 当前工作目录中的gph基名，将已有原生.gph模板复制入当前工作目录BWTL_UDF文件夹，不覆盖旧库条目。CREO_OP REUSE_UDF_INFO 模型 库名 读取真实必需参照的顺序和类型；CREO_OP REUSE_UDF_PLACE 模型 新组名 库名 参照1 参照2 [更多]，按读取的提示逐项绑定实际参照，采用模板默认变尺寸、同尺寸、独立放置。本版提供已存在原生gph入库及放置，不支持任意特征自动编写gph，也不假设库里已有用户公司模板。\n"
L"108：CREO_OP REUSE_PARAM 模型 新参数名 STRING|REAL|INTEGER|BOOLEAN 值 [MM]。只创建新参数，重名拒绝。字符串单个词，布尔TRUE或FALSE；REAL可带MM。修改已有参数仍使用原来的带旧值核验流程。\n"
L"109：CREO_OP REUSE_RELATION 模型 目标尺寸符号或实数参数 公式。公式不含空格，仅已存在数值符号和数字、+-*/()，例如 d5 d1*2+3。先在临时副本验证再追加原生关系，不覆盖旧关系或已被关系控制的目标，拒绝自引用或循环、除零和不合理几何。读取的尺寸值为模型原生单位，不能把它们直接假设成毫米。\n"
L"110：CREO_OP REUSE_FAMILY 模型 新母模型名 DIM:实际尺寸符号 规格值1 规格值2 [更多]。从当前模型生成独立母模型和2至8个族表实例；本版一列自由驱动尺寸，值按原生单位，必须先核对单位和符号。原模型保持，已有族表拒绝自动覆盖，实际实例重生成及尺寸读回后，保存新母模型和族表到当前工作目录下的新规格文件夹，不覆盖同名文件夹。此项会创建新文件，不能说已经保存源零件。\n";
#endif
